{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C55"],
      "claim": "Esaxerenone, a structurally close N-aryl amide with an ortho-substituted biaryl and polar heterocycle, has an absolute oral bioavailability of 89.0% in healthy subjects, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Glasdegib, an amide/urea-containing heteroaryl drug, has an absolute oral bioavailability of 77.12% in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Elinzanetant, which shares amide, morpholine/piperazine, and biaryl features with the query, has dose-independent oral bioavailability of 36.7%, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Tolfenamic acid has an absolute oral bioavailability of 61.6% in healthy volunteers, supporting high F for an amide-containing drug with similar lipophilic aromatic character.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Meloxicam, an amide-like heteroaryl drug, has an absolute oral bioavailability of 89% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Fasiglifam, a biaryl ether/carboxylic acid drug, is characterized by rapid absorption and high oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Nilotinib, a low-solubility amide/heteroaryl drug, has predicted bioavailability of 16% at 400 mg in fasted volunteers, providing a contradictory low-F anchor; however, the query's morpholine/pyridine motif is more solubilizing than nilotinib's core.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "Isradipine has systemic availability of 16.5% in volunteers, a contradictory low-F example, but its dihydropyridine ester structure is not closely analogous to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The preponderance of high-transfer human absolute bioavailability data from structurally related amide/heteroaryl drugs (esaxerenone ~90%, glasdegib ~77%, meloxicam ~89%, tolfenamic acid ~60%, elinzanetant ~37%) supports F >= 20%. The low-F analogues isradipine and nilotinib are less structurally aligned and are outweighed by the consistent high-F evidence.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself.",
    "No query-specific data on solubility-limited absorption or first-pass metabolism.",
    "Some analogue records come from disease populations (e.g., cirrhosis) with altered bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

